/*
 * The only way a Submission is ever created. A file's type is judged from _Files, which
 * the backend filled by sniffing the bytes (PLATFORM.md feature 1): the extension must
 * match what the bytes are, so a page renamed .pdf is refused and an .html is only ever
 * text/html (shown in the sandbox, PLATFORM.md feature 5). Office files and media sniff
 * as zip and octet-stream (defect D5), so those names are kept and the kind is read from them.
 * A file version carries 1 to 5 files (`files`, stored names), reviewed as one (DECISIONS 2026-11-12).
 * The page offers the same list (Option sets/Hand-in file types); this one is the gate.
 * DBU-09: `addToCreations` also keeps it in My creations, pointing at this version (never a copy).
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const MAX_BYTES = 50 * 1024 * 1024;
    const MAX_FILES = 5;
    const MEDIA = ['application/octet-stream'];
    const OFFICE = ['application/zip'];
    const TYPES = {
      pdf: ['application/pdf'], docx: OFFICE, pptx: OFFICE, xlsx: OFFICE,
      html: ['text/html'], htm: ['text/html'],
      png: ['image/png'], jpg: ['image/jpeg'], jpeg: ['image/jpeg'], webp: ['image/webp'],
      mp3: ['audio/mpeg'], m4a: MEDIA.concat(['audio/mp4']), mp4: MEDIA.concat(['video/mp4']), webm: MEDIA.concat(['video/webm', 'audio/webm'])
    };

    const stepId = String(Inputs.stepId || '');
    const steps = stepId ? await q('Step', { objectId: { equalTo: stepId } }) : [];
    const step = steps[0];
    if (!step || step.learner !== me || step.shared !== true || step.kind !== 'homework') return refuse('This homework is not one of yours. Reload the page.');
    if (step.status === 'approved') return refuse('This homework is already approved, so it takes no new version.');

    const note = String(Inputs.note || '').trim();
    if (note.length > 2000) return refuse('Keep the note under 2,000 characters.');
    const kind = String(Inputs.kind || '');
    const row = { step: stepId, learner: me, kind, note: note || null, review: 'pending' };

    if (kind === 'file') {
      // Each file is checked on its own; a refusal names the file when there are several.
      const names = Array.isArray(Inputs.files) ? Inputs.files.map((x) => String(x || '')).filter(Boolean) : [];
      if (!names.length) return refuse('Choose a file to hand in.');
      if (names.length > MAX_FILES) return refuse('Hand in up to ' + MAX_FILES + ' files in one version.');
      if (new Set(names).size !== names.length) return refuse('The same file is in this version twice. Remove one and hand in again.');
      const files = [];
      for (const name of names) {
        const rows = await q('_Files', { storedName: { equalTo: name } });
        const f = rows.length === 1 ? rows[0] : null;
        const owner = f && f.owner && typeof f.owner === 'object' ? f.owner.objectId : f && f.owner;
        // Never name a file that is not the caller's: its name is someone else's.
        if (!f || owner !== me) return refuse((names.length > 1 ? 'One of these files is' : 'That file is') + ' not one you uploaded. Choose it and upload it again.');
        const original = String(f.originalName || '');
        const said = (why) => refuse(names.length > 1 ? original + ': ' + why : why);
        if (f.private !== true) return said('That file was not uploaded privately. Choose it and upload it again.');
        if (Number(f.size) > MAX_BYTES) return said('That file is larger than 50 MB. Put it online and hand in a link instead.');
        const dot = original.lastIndexOf('.');
        const ext = dot > 0 ? original.slice(dot + 1).toLowerCase() : '';
        const allowed = TYPES[ext];
        if (!allowed) return said('Files of this kind can\'t be handed in. Use Word, PowerPoint, Excel, PDF, HTML, an image (PNG, JPG, WebP), audio (MP3, M4A) or video (MP4, WebM), or hand in a link.');
        if (!allowed.includes(f.contentType)) return said('This file is not a real .' + ext + ' file. Save it again in that format, then hand it in.');
        files.push({ file: name, fileName: original });
      }
      row.files = files;
    } else if (kind === 'link') {
      const url = String(Inputs.url || '').trim();
      let ok = false;
      try { const u = new URL(url); ok = (u.protocol === 'https:' || u.protocol === 'http:') && !!u.hostname; } catch (e) { ok = false; }
      if (!ok) return refuse('That is not a web address. Links start with https://');
      if (url.length > 2000) return refuse('That link is too long. Use a shorter share link.');
      row.url = url;
    } else if (kind === 'text') {
      const text = String(Inputs.text || '');
      if (!text.trim()) return refuse('Write or paste something to hand in.');
      if (text.length > 50000) return refuse('That is too long to paste. Keep it under 50,000 characters, or hand it in as a file.');
      row.text = text;
    } else {
      return refuse('Choose a file, a link or some text to hand in.');
    }

    // (step, version) is unique: two hand-ins at once cannot share a number; the later one takes the next.
    let created = null;
    for (let attempt = 0; attempt < 3 && !created; attempt++) {
      const versions = await q('Submission', { step: { equalTo: stepId } });
      row.version = versions.reduce((m, v) => Math.max(m, Number(v.version) || 0), 0) + 1;
      try {
        created = await Noodl.Records.create('Submission', row, { plain: true });
      } catch (e) {
        if (attempt === 2) throw e;
      }
    }
    const submissionId = created.objectId || created.id;
    if (step.status !== 'handed_in') {
      await Noodl.Records.save(stepId, { status: 'handed_in' }, { className: 'Step' });
    }

    // DBU-09, "Also add it to My creations": one creation per homework. A later version moves the
    // pointer of the one already there (keeping the learner's title and words); none is made twice.
    // Its kind is a first guess from what was handed in; the learner can change it.
    let creationId = null;
    if (Inputs.addToCreations === true) {
      const mine = (await q('Creation', { fromStep: { equalTo: stepId } })).filter((c) => c.learner === me);
      const kept = mine.find((c) => c.submission);
      if (kept) {
        await Noodl.Records.save(kept.objectId, { submission: submissionId }, { className: 'Creation' });
        creationId = kept.objectId;
      } else {
        const KIND_OF = { docx: 'document', pptx: 'document', xlsx: 'document', pdf: 'document', html: 'interactive', htm: 'interactive', mp3: 'audio_video', m4a: 'audio_video', mp4: 'audio_video', webm: 'audio_video' };
        const firstName = kind === 'file' ? String(row.files[0].fileName || '') : '';
        const ext = firstName.lastIndexOf('.') > 0 ? firstName.slice(firstName.lastIndexOf('.') + 1).toLowerCase() : '';
        const guess = kind === 'link' ? 'link' : kind === 'text' ? 'prompt' : (KIND_OF[ext] || 'other');
        const made = await Noodl.Records.create('Creation', {
          learner: me, title: step.title, kind: guess, fromStep: stepId, submission: submissionId, usedInClass: false
        }, { plain: true });
        creationId = made.objectId || made.id;
      }
    }

    await Noodl.Records.create('Doorbell', { learner: me, topic: 'submission' },
      { acl: { [me]: { read: true }, 'role:staff': { read: true } } });

    Outputs.submissionId = submissionId;
    Outputs.version = row.version;
    Outputs.creationId = creationId;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:handIn]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
